UPDATE businesses SET description = 'Barksole Sea Point is the Main Road branch of the Barksole shoe repair chain, best known for fixing and restoring footwear so customers can keep wearing the shoes they love. Its craftsmen repair heels, soles and stitching on everything from work shoes and boots to high heels and everyday sneakers, often saving a favourite pair from the bin.

Alongside shoe repairs, the branch offers a range of handy services under one roof, including key cutting, printing, dry cleaning drop-off and custom-made rubber stamps for businesses and personal use. That mix makes it a practical stop for ticking off several errands at once. Being right on busy Main Road, it is easy for Sea Point residents and people working nearby to drop items off and collect them on the way home. Barksole is at 154 Main Road, Sea Point, Cape Town.', description_enriched_at = datetime('now') WHERE slug = 'barksole-sea-point-sea-point' AND description = 'Barksole Sea Point is the Main Road branch of the Barksole shoe repair and shoe care chain, in Sea Point.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
